<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from "vue";
import { useI18n } from "vue-i18n";
import { ArrowLeft, ArrowRight, Clock, Close, Collection, EditPen, Loading, Plus, Refresh, VideoPlay } from "@element-plus/icons-vue";
import { api } from "@/api/client";
import type { ModelInfo, ScheduleJob, ScheduleRunRecord, ScheduleRunsInfo } from "@/api/types";
import { describeSchedule, runState, scheduleDate, scheduleTimezoneLabel, scheduleNeedsAttention, scheduleState, scheduleTitle, type ScheduleDraft } from "@/agent/schedulePresentation";
import { inputPartsBlocks } from "@/agent/orderedInput";
import OrderedMessageContent from "./OrderedMessageContent.vue";
import ScheduleEditorDialog, { type ScheduleAgentOption } from "./ScheduleEditorDialog.vue";
import ConfirmDialog from "./ConfirmDialog.vue";

const props = withDefaults(defineProps<{ modelValue: boolean; agentId?: string; agentName?: string; sessionId?: string | null; agents?: ScheduleAgentOption[]; models?: ModelInfo[]; initialDraft?: ScheduleDraft | null; isAdmin?: boolean; draftBusy?: boolean }>(), { agentId: "", agentName: "", sessionId: "", agents: () => [], models: () => [], initialDraft: null, isAdmin: false, draftBusy: false });
const emit = defineEmits<{ "update:modelValue": [boolean]; attention: [boolean]; "open-session": [sessionId: string, label: string, agentId?: string]; "request-draft": []; saved: [job: ScheduleJob] }>();
const { t, locale } = useI18n();
const jobs = ref<ScheduleJob[]>([]), loading = ref(false), loadError = ref(""), actionError = ref(""), actionId = ref("");
const query = ref(""), stateFilter = ref("all");
const selectedId = ref(""), mobileDetail = ref(false), detailTab = ref<"result" | "instructions" | "history">("result");
const runs = ref<ScheduleRunsInfo | null>(null), runsLoading = ref(false), runsError = ref("");
const backend = ref(""), directory = ref(""), serverZone = ref(""), serverZoneLabel = ref("");
const editorVersion = ref(0);
const editorOpen = ref(false), editing = ref<ScheduleJob | null>(null), editorDraft = ref<ScheduleDraft | null>(null);
const editor = ref<InstanceType<typeof ScheduleEditorDialog> | null>(null), confirm = ref<InstanceType<typeof ConfirmDialog> | null>(null);
let disposed = false, loadSequence = 0, runsSequence = 0, draftSequence = 0, pollTimer: ReturnType<typeof setTimeout> | undefined;
let acceptedDraftContext = "";
const context = () => JSON.stringify([props.agentId, props.sessionId]);
const isCurrentJob = (job: ScheduleJob) => !!props.agentId && job.agent_id === props.agentId && !job.workflow_id;
const selected = computed(() => jobs.value.find(job => job.id === selectedId.value && isCurrentJob(job)) || null);
const filtered = computed(() => jobs.value.filter(job => (!query.value.trim() || `${scheduleTitle(job)}\n${job.agent_name || ""}\n${job.prompt}`.toLocaleLowerCase().includes(query.value.trim().toLocaleLowerCase())) && (stateFilter.value === "all" || stateFilter.value === "attention" && scheduleNeedsAttention(job) || stateFilter.value === "running" && job.running || stateFilter.value === "paused" && ["paused", "autoPaused", "expired"].includes(scheduleState(job)))).sort((a, b) => Number(scheduleNeedsAttention(b)) - Number(scheduleNeedsAttention(a)) || Number(!!b.running) - Number(!!a.running) || new Date(b.created_at).getTime() - new Date(a.created_at).getTime()));
const attentionCount = computed(() => jobs.value.filter(scheduleNeedsAttention).length);
const taskTitle = (job: ScheduleJob) => scheduleTitle(job);
const stateKey = (job: ScheduleJob) => scheduleState(job);
const turnLabel = (job: ScheduleJob) => job.turn_limit_mode === "unlimited" ? t("scheduleDialog.unlimitedTurns") : job.max_turns || t("scheduleDialog.agentTurnDefault");
const approvalLabel = (job: ScheduleJob) => t(`scheduleDialog.approval_${job.approval_mode || "standard"}`);
const displayDate = (iso: string | null | undefined, job?: ScheduleJob) => scheduleDate(iso, job?.timezone || job?.effective_timezone || serverZone.value || undefined, locale.value);
const editable = (job: ScheduleJob) => isCurrentJob(job) && !job.running;
const canRun = (job: ScheduleJob) => isCurrentJob(job) && !job.running && !job.availability_error && stateKey(job) !== "expired";
const describe = (job: ScheduleJob) => { try { return describeSchedule(job, t); } catch { return job.cron || job.kind; } };
const selectedBlocks = computed(() => selected.value ? inputPartsBlocks(selected.value.parts?.length ? selected.value.parts : [{ type: "text", text: selected.value.prompt }]) : []);
function errorText(error: unknown) { return error instanceof Error ? error.message : String(error); }
function schedulePoll() { clearTimeout(pollTimer); if (!props.modelValue || disposed) return; pollTimer = setTimeout(async () => { await load(true); if (selected.value && !editorOpen.value) await loadRuns(selected.value); schedulePoll(); }, jobs.value.some(job => job.running) ? 3000 : 15000); }
async function load(silent = false) {
  const ticket = ++loadSequence, origin = context();
  if (!props.agentId) { jobs.value = []; loading.value = false; loadError.value = t("scheduleDialog.agentRequired"); return; }
  if (!silent) loading.value = true; loadError.value = "";
  try {
    const info = await api.scheduleJobs({ scope: "agent", agent_id: props.agentId });
    if (disposed || ticket !== loadSequence || origin !== context() || !props.modelValue) return;
    jobs.value = (info.jobs || []).filter(isCurrentJob); backend.value = info.backend; directory.value = info.dir; serverZone.value = info.server_timezone || ""; serverZoneLabel.value = info.server_timezone_label || "";
    if (!jobs.value.some(job => job.id === selectedId.value)) { selectedId.value = filtered.value[0]?.id || ""; runs.value = null; }
    emit("attention", jobs.value.some(scheduleNeedsAttention));
  } catch (error) { if (!disposed && ticket === loadSequence && origin === context() && props.modelValue) loadError.value = errorText(error); }
  finally { if (!disposed && ticket === loadSequence) loading.value = false; }
}
async function loadRuns(job: ScheduleJob) {
  if (!isCurrentJob(job)) return;
  const ticket = ++runsSequence, origin = context(); runsLoading.value = true; runsError.value = "";
  try { const result = await api.scheduleRuns(job.id); if (!disposed && ticket === runsSequence && origin === context() && selectedId.value === job.id && props.modelValue) runs.value = result; }
  catch (error) { if (!disposed && ticket === runsSequence && origin === context() && selectedId.value === job.id && props.modelValue) runsError.value = errorText(error); }
  finally { if (!disposed && ticket === runsSequence) runsLoading.value = false; }
}
async function selectJob(job: ScheduleJob) { if (!isCurrentJob(job)) return; selectedId.value = job.id; mobileDetail.value = true; detailTab.value = "result"; actionError.value = ""; runs.value = null; await loadRuns(job); }
async function confirmEditorLeave() { if (editorOpen.value && editor.value && !await editor.value.confirmLeave()) return false; return true; }
async function openCreate(draft?: ScheduleDraft | null) {
  if (!props.agentId || draft?.agent_id && draft.agent_id !== props.agentId) { actionError.value = t("scheduleDialog.contextChanged"); return; }
  const ticket = ++draftSequence, origin = context(); if (!await confirmEditorLeave() || disposed || ticket !== draftSequence || origin !== context() || !props.modelValue) return;
  editing.value = null; editorDraft.value = draft ? JSON.parse(JSON.stringify(draft)) : null; editorVersion.value++; editorOpen.value = true;
}
async function openEdit(job: ScheduleJob) {
  if (!editable(job) || actionId.value) return;
  const origin = context(), ticket = ++draftSequence; if (!await confirmEditorLeave() || disposed || ticket !== draftSequence || origin !== context() || !props.modelValue) return;
  actionId.value = job.id; actionError.value = "";
  try { const result = await api.scheduleJob(job.id); if (disposed || origin !== context() || ticket !== draftSequence || !props.modelValue) return; if (!isCurrentJob(result.job)) { actionError.value = t("scheduleDialog.contextChanged"); return; } editing.value = result.job; editorDraft.value = null; editorVersion.value++; editorOpen.value = true; }
  catch (error) { if (!disposed && origin === context()) actionError.value = errorText(error); }
  finally { if (!disposed && origin === context()) actionId.value = ""; }
}
async function requestDraft() { const origin = context(), ticket = ++draftSequence; if (!await confirmEditorLeave() || disposed || ticket !== draftSequence || origin !== context() || !props.modelValue) return; acceptedDraftContext = origin; emit("request-draft"); }
async function saved(job: ScheduleJob) { if (disposed || !props.modelValue || !isCurrentJob(job)) return; emit("saved", job); selectedId.value = job.id; mobileDetail.value = true; detailTab.value = "result"; await load(true); if (selected.value) await loadRuns(selected.value); }
async function mutate(job: ScheduleJob, action: "pause" | "resume" | "run" | "remove") {
  if (actionId.value || disposed || !props.modelValue || !isCurrentJob(job) || action === "run" && !canRun(job)) return;
  const origin = context();
  if (action === "remove" && !await confirm.value?.ask({ title: t("scheduleDialog.deleteTitle"), body: t("scheduleDialog.deleteBody", { title: taskTitle(job) }), confirmText: t("scheduleDialog.deletePlan"), cancelText: t("scheduleDialog.cancel"), danger: true })) return;
  if (disposed || origin !== context() || !props.modelValue) return;
  actionId.value = job.id; actionError.value = "";
  try {
    if (action === "run") await api.scheduleRunNow(job.id);
    else if (action === "remove") await api.scheduleDeleteJob(job.id);
    else await api.scheduleSetEnabled(job.id, action === "resume");
    if (disposed || origin !== context() || !props.modelValue) return;
    await load(true); if (selected.value) await loadRuns(selected.value); schedulePoll();
  } catch (error) { if (!disposed && origin === context()) actionError.value = errorText(error); }
  finally { if (!disposed && origin === context()) actionId.value = ""; }
}
function openResult(job: ScheduleJob, run?: ScheduleRunRecord) {
  if (!isCurrentJob(job)) return;
  const session = run?.session_id || job.running_session_id || job.session_id; if (!session) return;
  emit("open-session", session, taskTitle(job), job.agent_id);
}
async function close() { const origin = context(); if (!await confirmEditorLeave() || disposed || origin !== context()) return; editorOpen.value = false; emit("update:modelValue", false); }
watch(() => [props.modelValue, props.agentId, props.sessionId] as const, ([open]) => { loadSequence++; runsSequence++; draftSequence++; clearTimeout(pollTimer); if (!open) { editorOpen.value = false; editing.value = null; editorDraft.value = null; acceptedDraftContext = ""; loading.value = false; runsLoading.value = false; actionId.value = ""; return; } actionId.value = ""; actionError.value = ""; jobs.value = []; selectedId.value = ""; runs.value = null; mobileDetail.value = false; void load().then(() => { if (selected.value) void loadRuns(selected.value); schedulePoll(); }); }, { immediate: true });
watch(() => props.initialDraft?.key, async key => { if (!key || !props.initialDraft || !props.modelValue) return; const draft = props.initialDraft; if (acceptedDraftContext === context()) { acceptedDraftContext = ""; editorOpen.value = false; await openCreate(draft); } else await openCreate(draft); }, { immediate: true });
onBeforeUnmount(() => { disposed = true; loadSequence++; runsSequence++; draftSequence++; clearTimeout(pollTimer); });
</script>
<template>
  <el-dialog :model-value="modelValue" fullscreen append-to-body :show-close="false" :close-on-click-modal="false" :close-on-press-escape="false" class="schedule-center-dialog" data-testid="schedule-center" :before-close="close">
    <template #header><header class="schedule-header"><div class="schedule-brand"><span><el-icon><Clock /></el-icon></span><div><h1>{{ t('scheduleDialog.title') }}</h1><p>{{ t('scheduleDialog.centerHint') }}</p></div></div><div class="schedule-header-actions"><button class="schedule-primary" type="button" :disabled="draftBusy || !agentId" data-testid="schedule-create" @click="openCreate()"><el-icon><Plus /></el-icon>{{ t('scheduleDialog.newTask') }}</button><button class="schedule-icon" type="button" :aria-label="t('scheduleDialog.close')" data-testid="schedule-close" @click="close"><el-icon><Close /></el-icon></button></div></header></template>
    <div class="schedule-center-layout" :class="{ 'show-mobile-detail': mobileDetail }"><aside class="schedule-list-pane"><div class="schedule-filter-row"><input v-model="query" type="search" :placeholder="t('scheduleDialog.search')" :aria-label="t('scheduleDialog.search')" data-testid="schedule-search" /><select v-model="stateFilter" :aria-label="t('scheduleDialog.filterState')"><option value="all">{{ t('scheduleDialog.filterAll') }}</option><option value="attention">{{ t('scheduleDialog.filterAttention') }}</option><option value="running">{{ t('scheduleDialog.state_running') }}</option><option value="paused">{{ t('scheduleDialog.filterPaused') }}</option></select></div><div class="schedule-list-summary"><span>{{ t('scheduleDialog.taskCount', { n: filtered.length }) }}<template v-if="attentionCount"> · {{ t('scheduleDialog.attentionCount', { n: attentionCount }) }}</template></span><button type="button" class="schedule-icon" :disabled="loading" :aria-label="t('scheduleDialog.refresh')" @click="load()"><el-icon :class="{ 'is-loading': loading }"><Refresh /></el-icon></button></div><p v-if="loadError" class="schedule-error" role="alert">{{ loadError }} <button class="schedule-link" type="button" @click="load()">{{ t('scheduleDialog.retry') }}</button></p><div v-if="loading && !jobs.length" class="schedule-empty">{{ t('scheduleDialog.loading') }}</div><div v-else-if="!filtered.length" class="schedule-empty"><el-icon><Clock /></el-icon><strong>{{ t(query || stateFilter !== 'all' ? 'scheduleDialog.noResults' : 'scheduleDialog.empty') }}</strong><p>{{ t('scheduleDialog.emptyAgentHint') }}</p><button v-if="!query && agentId" type="button" class="schedule-link" @click="openCreate()">{{ t('scheduleDialog.emptyCreate') }}</button></div><div class="schedule-list" data-testid="schedule-list"><button v-for="job in filtered" :key="job.id" type="button" class="schedule-task" :class="{ selected: selectedId === job.id }" :data-job-id="job.id" data-testid="schedule-item" @click="selectJob(job)"><div class="schedule-task-heading"><strong>{{ taskTitle(job) }}</strong><span class="schedule-status" :class="stateKey(job)">{{ t(`scheduleDialog.state_${stateKey(job)}`) }}</span></div><span class="schedule-task-owner">{{ job.agent_name || agentName }}</span><span class="schedule-task-result">{{ job.availability_error || job.last_error || job.last_summary || t('scheduleDialog.noResultYet') }}</span><span class="schedule-task-next"><el-icon><Clock /></el-icon>{{ job.next_run ? t('scheduleDialog.nextRunAt', { time: displayDate(job.next_run, job) }) : t('scheduleDialog.nextRunNone') }}</span></button></div><p class="schedule-server-note">{{ t('scheduleDialog.serverRuntimeShort') }}</p></aside>
    <main class="schedule-detail-pane"><template v-if="selected"><header class="schedule-detail-header"><button type="button" class="schedule-icon schedule-mobile-back" :aria-label="t('scheduleDialog.backToList')" @click="mobileDetail = false"><el-icon><ArrowLeft /></el-icon></button><div><span>{{ selected.agent_name || agentName }}</span><h2>{{ taskTitle(selected) }}</h2></div><button v-if="selected.agent_id" type="button" class="schedule-secondary" :disabled="!editable(selected) || !!actionId" data-testid="schedule-edit" @click="openEdit(selected)"><el-icon><EditPen /></el-icon>{{ t('scheduleDialog.edit') }}</button></header><p v-if="actionError" class="schedule-error" role="alert">{{ actionError }}</p><div class="schedule-detail-overview"><span class="schedule-status" :class="stateKey(selected)">{{ t(`scheduleDialog.state_${stateKey(selected)}`) }}</span><span>{{ describe(selected) }}</span><span class="schedule-timezone">{{ scheduleTimezoneLabel(selected.timezone || selected.effective_timezone_label || selected.effective_timezone || serverZoneLabel) }}</span></div><div class="schedule-task-actions"><button type="button" class="schedule-primary" :disabled="!!actionId || !canRun(selected)" data-testid="schedule-run-now" @click="mutate(selected, 'run')"><el-icon><Loading v-if="actionId === selected.id" class="is-loading" /><VideoPlay v-else /></el-icon>{{ t(selected.last_run_status === 'error' ? 'scheduleDialog.retryRun' : 'scheduleDialog.runNow') }}</button><button type="button" class="schedule-secondary" :disabled="!!actionId || stateKey(selected) === 'expired' || (!selected.enabled && !!selected.availability_error)" data-testid="schedule-toggle-enabled" @click="mutate(selected, selected.enabled ? 'pause' : 'resume')">{{ t(selected.enabled ? 'scheduleDialog.pause' : 'scheduleDialog.resume') }}</button><span v-if="selected.running" class="schedule-action-note">{{ t('scheduleDialog.runningEditHint') }}</span><button v-if="selected.agent_id && !selected.running" type="button" class="schedule-link danger" data-testid="schedule-remove" :disabled="!!actionId" @click="mutate(selected, 'remove')">{{ t('scheduleDialog.deletePlan') }}</button></div><nav class="schedule-detail-tabs" :aria-label="t('scheduleDialog.details')"><button v-for="tab in ['result','instructions','history'] as const" :key="tab" type="button" :class="{ active: detailTab === tab }" :aria-pressed="detailTab === tab" :data-testid="`schedule-tab-${tab}`" @click="detailTab = tab">{{ t(`scheduleDialog.tab_${tab}`) }}</button></nav><div class="schedule-detail-body"><section v-if="detailTab === 'result'" class="schedule-result" data-testid="schedule-result"><template v-if="selected.running_session_id || selected.session_id"><div class="schedule-result-head"><div><small>{{ t(selected.running ? 'scheduleDialog.currentRun' : 'scheduleDialog.lastResult') }}</small><strong>{{ displayDate(selected.last_run_at, selected) }}</strong></div><button type="button" class="schedule-secondary" data-testid="schedule-open-result" @click="openResult(selected)">{{ t(selected.waiting_human ? 'scheduleDialog.handleApproval' : selected.running ? 'scheduleDialog.viewProgress' : 'scheduleDialog.openResult') }}<el-icon><ArrowRight /></el-icon></button></div><p v-if="selected.last_summary" class="schedule-result-prose">{{ selected.last_summary }}</p><p v-else class="schedule-muted">{{ t(selected.running ? 'scheduleDialog.resultWhileRunning' : 'scheduleDialog.resultInConversation') }}</p></template><div v-else class="schedule-no-result"><el-icon><Collection /></el-icon><h3>{{ t('scheduleDialog.noResultYet') }}</h3><p>{{ t('scheduleDialog.noResultHint') }}</p></div><div v-if="selected.last_error || selected.availability_error" class="schedule-failure"><strong>{{ t('scheduleDialog.needsAttention') }}</strong><p>{{ selected.availability_error || selected.last_error }}</p></div><dl class="schedule-result-facts"><div><dt>{{ t('scheduleDialog.nextRunLabel') }}</dt><dd>{{ displayDate(selected.next_run, selected) }}</dd></div><div><dt>{{ t('scheduleDialog.validUntil') }}</dt><dd>{{ selected.expires_at ? displayDate(selected.expires_at, selected) : t('scheduleDialog.neverExpires') }}</dd></div></dl></section><section v-else-if="detailTab === 'instructions'" data-testid="schedule-description"><div class="schedule-description-content"><OrderedMessageContent :blocks="selectedBlocks" :parse-skill="false" /></div><dl class="schedule-result-facts"><div><dt>{{ t('scheduleDialog.runBy') }}</dt><dd>{{ selected.agent_name || t('scheduleDialog.legacyTask') }}</dd></div><div><dt>{{ t('scheduleDialog.model') }}</dt><dd>{{ selected.agent_model || selected.model || t('scheduleDialog.followsAgent') }}</dd></div><div><dt>{{ t('scheduleDialog.timezone') }}</dt><dd>{{ scheduleTimezoneLabel(selected.timezone || selected.effective_timezone_label || serverZoneLabel) }}</dd></div><div><dt>{{ t('scheduleDialog.turnLimit') }}</dt><dd>{{ turnLabel(selected) }}</dd></div><div><dt>{{ t('scheduleDialog.approvalLabel') }}</dt><dd>{{ approvalLabel(selected) }}</dd></div></dl><details class="schedule-diagnostics"><summary>{{ t('scheduleDialog.technicalDetails') }}</summary><p>ID: {{ selected.id }}</p><p>{{ backend }} · {{ directory }}</p><code v-if="selected.cron">{{ selected.cron }}</code></details></section><section v-else class="schedule-history" data-testid="schedule-history"><div class="schedule-history-heading"><p>{{ t('scheduleDialog.historyHint') }}</p><button class="schedule-secondary" type="button" :disabled="runsLoading" @click="loadRuns(selected)">{{ t('scheduleDialog.refresh') }}</button></div><p v-if="runsError" class="schedule-error" role="alert">{{ runsError }} <button type="button" class="schedule-link" data-testid="schedule-runs-retry" @click="loadRuns(selected)">{{ t('scheduleDialog.retry') }}</button></p><p v-else-if="runsLoading && !runs" class="schedule-muted">{{ t('scheduleDialog.loading') }}</p><div v-else-if="!runs?.runs.length" class="schedule-no-result"><h3>{{ t('scheduleDialog.runsEmpty') }}</h3></div><article v-for="(run, index) in runs?.runs || []" :key="`${run.ts}-${index}`" class="schedule-run" data-testid="schedule-run"><div class="schedule-run-head"><span class="schedule-status" :class="runState(run)">{{ t(`scheduleDialog.state_${runState(run)}`) }}</span><time>{{ displayDate(run.ts, selected) }}</time><span>{{ t(run.trigger === 'manual' ? 'scheduleDialog.triggerManual' : 'scheduleDialog.triggerScheduled') }}</span><button v-if="run.session_id" type="button" class="schedule-link" @click="openResult(selected, run)">{{ t('scheduleDialog.openResult') }} →</button></div><p v-if="run.error" class="schedule-run-error">{{ run.error }}</p><p v-else-if="run.summary" class="schedule-run-summary">{{ run.summary }}</p><div class="schedule-run-meta"><span>{{ t('scheduleDialog.durationSec', { s: run.duration_sec.toFixed(1) }) }}</span><span v-if="run.model">{{ run.model }}</span><span v-if="run.agent_revision">{{ t('scheduleDialog.agentVersion', { n: run.agent_revision }) }}</span><span v-if="run.end_reason">{{ run.end_reason }}</span></div></article><details v-if="runs?.log_tail.length" class="schedule-diagnostics"><summary>{{ t('scheduleDialog.logTitle') }}</summary><pre>{{ runs.log_tail.join('\n') }}</pre></details></section></div></template><div v-else class="schedule-select-empty"><el-icon><Clock /></el-icon><h2>{{ t('scheduleDialog.chooseTask') }}</h2><p>{{ t('scheduleDialog.chooseTaskHint') }}</p></div></main></div>
  </el-dialog>
  <ScheduleEditorDialog :key="editorVersion" ref="editor" v-model="editorOpen" :item="editing" :draft="editorDraft" :agent-id="agentId" :agent-name="agentName" :session-id="sessionId" :agents="agents" :models="models" :server-timezone="serverZone" :server-timezone-label="serverZoneLabel" :draft-busy="draftBusy" @saved="saved" @request-draft="requestDraft" /><ConfirmDialog ref="confirm" />
</template>
